/* UI-only adapter. No wallet SDK, RPC, backend or game engine is imported. */
(()=>{'use strict';
const gameAvailable=document.body.dataset.gameAvailable==='true';
const KEY='supply-line-interface-demo-v1',SCHEMA=1,BASE=1000000n,FEE_BPS=300n;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='',disabled=false)=>`<button type="button" class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
const pill=(text,type='')=>`<span class="pill ${type}">${text}</span>`;
const notice=(title,body='',type='')=>`<div class="notice ${type}" role="${type==='error'?'alert':'status'}"><strong>${title}</strong>${body?`<p>${body}</p>`:''}</div>`;
const wait=(title,body)=>`<div class="status-box" role="status"><h3><span class="spinner" aria-hidden="true"></span>${title}</h3><p class="small no-margin">${body}</p></div>`;
const money=(n,places=null)=>{n=BigInt(n);const digits=String(n%BASE).padStart(6,'0');return `${n/BASE}.${places===null?digits.replace(/0+$/,'').padEnd(2,'0'):digits.slice(0,places)}`;};
function parseStake(s){if(!/^\d{1,3}(\.\d{1,2})?$/.test(s))return null;const [a,b='']=s.split('.');const n=BigInt(a)*BASE+BigInt(b.padEnd(6,'0'));return n>=BASE&&n<=100n*BASE?n:null;}
function amounts(override=null){const stake=BigInt(override??(state.match?.stake||parseStake(state.amount)||5000000n)),pool=stake*2n,fee=pool*FEE_BPS/10000n;return{stake,pool,fee,prize:pool-fee};}
function fresh(){return{schema:SCHEMA,page:'home',amount:'5.00',wallet:null,source:'near',paymentConnected:false,match:null,swap:'idle',deposit:'idle',quoteUntil:0,quoteStatus:'idle',balances:{usdc:'20000000',near:'10000000',eth:'20000'},events:[],history:[],nextId:1,pending:null,hold:false,connection:'connected',error:'',outcome:'won',payout:'idle',feePayout:'idle',refund:'idle',tab:'all',note:'',paymentOutcome:'success',joinCode:''};}
let state=fresh(),resumed=false,timer=null,modalReturn=null,focusedBefore=null,toastTimer=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.schema===SCHEMA){state={...fresh(),...saved};resumed=state.page!=='home';if(state.pending){const kind=state.pending.kind;state.pending=null;if(kind==='swap')state.swap='unknown';if(kind==='deposit')state.deposit='unknown';if(kind==='payout')state.payout='unknown';if(kind==='refund')state.refund='unknown';if(kind==='wallet')state.error='Connection interrupted. Connect the demo account again.';if(kind==='countdown')state.match.status='ready';}}}catch{}
const sources={near:{name:'NEAR',network:'NEAR',unit:2n*BASE,places:4,balanceKey:'near',description:'Convert NEAR to USDC in your NEAR account.'},eth:{name:'ETH',network:'Ethereum',unit:2500n*BASE,places:6,balanceKey:'eth',description:'Mock cross-network route. Asset support is not verified.'},usdc:{name:'USDC',network:'NEAR',unit:BASE,places:2,balanceKey:'usdc',description:'Use your existing demo USDC. No conversion needed.'}};
const scenarios=[
 ['home','Main menu'],['create','Create lobby'],['waiting','Waiting for opponent'],['funding','Opponent joined · fund stake'],['quote-expired','Quote expired'],['no-route','Route unavailable'],['low-balance','Insufficient balance'],['wrong-network','Wrong payment network'],['cancelled-signature','Transaction cancelled'],['converting','Converting funds'],['swap-failed','Conversion failed'],['swap-refund','Swap refund pending'],['swap-refunded','Swap refund confirmed'],['swap-unknown','Conversion status unknown'],['converted','Swap completed · stake not locked'],['awaiting-deposit','Awaiting stake confirmation'],['deposit-rejected','Deposit not accepted'],['deposit-unknown','Deposit status unknown'],['locked','Stake locked · waiting for opponent'],['ready','Both players ready'],['starting','Starting match'],['expired','Lobby expired · swap completed'],['expired-locked','Lobby expired · stake locked'],['full','Lobby is full'],['self-join','Already in this lobby'],['active','Match in progress'],['disconnected','Connection lost'],['account-changed','Account changed'],['won','You won · payout pending'],['lost','You lost'],['draw','Draw · refund pending'],['payout-sent','Payout sent'],['payout-error','Payout action required'],['payout-unknown','Payout status unknown'],['payout-confirmed','Payout confirmed'],['fee-pending','Prize paid · game fee pending'],['cancel-refund','Lobby cancelled · refund pending'],['refund-error','Refund action required'],['refund-sent','Refund sent'],['refund-confirmed','Refund confirmed'],['server-refund','Match interrupted · refund'],['matches','My matches']
];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{}}
function record(type,detail){const id=`DEMO-TX-${String(state.nextId++).padStart(4,'0')}`;state.events.unshift({id,type,detail,time:new Date().toISOString()});return id;}
function toast(t){clearTimeout(toastTimer);$('#toast').hidden=false;$('#toast').textContent=t;toastTimer=setTimeout(()=>$('#toast').hidden=true,3500);}
function clearPending(){clearTimeout(timer);timer=null;state.pending=null;}
function go(page){state.page=page;state.error='';render(true);}
function account(){return state.match?.account||state.wallet||'alex.demo.near';}
function sameAccount(){return !state.match||state.wallet===state.match.account;}
function activeMatch(){return state.match&&!['completed','cancelled','expired'].includes(state.match.status);}
function hasObligation(){return ['pending','unknown','refund-pending'].includes(state.swap)||['pending','unknown'].includes(state.deposit)||state.match&&(['pending','sent','unknown','error'].includes(state.payout)||['pending','sent','unknown','error'].includes(state.refund)||state.feePayout==='pending');}
function mkMatch(opponent=false){const a=amounts();state.match={id:'SL-DEMO-42',stake:String(a.stake),account:state.wallet||'alex.demo.near',opponent:opponent?'riley.demo.near':null,opponentLocked:false,status:opponent?'funding':'open',deadline:Date.now()+600000,time:0,progress:0,rivalProgress:0};state.swap='idle';state.deposit='idle';state.quoteStatus='idle';state.quoteUntil=0;state.events=[];state.payout='idle';state.refund='idle';state.feePayout='idle';state.error='';}
function heading(kicker,title,subtitle='',right=''){return`<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>`;}
function shell(html){return`<div class="container">${resumed?`<div class="session-note">${notice('Demo session restored','Your prototype state was restored from this browser. Pending operations require a status check.')} </div>`:''}${html}</div>`;}
function back(page='online'){return button('← '+(page==='home'?'Main menu':'Play online'),page,'back');}
function financials(showStake=true,override=null){const a=amounts(override);return`<dl class="ledger">${showStake?`<div><dt>Stake per player</dt><dd>${money(a.stake)} USDC</dd></div>`:''}<div><dt>Prize pool · 2 players</dt><dd>${money(a.pool)} USDC</dd></div><div><dt>Game fee · demo 3%</dt><dd>${money(a.fee)} USDC</dd></div><div class="total"><dt>Winner receives</dt><dd>${money(a.prize)} <span class="small">USDC</span></dd></div></dl><p class="small">Settled in USDC on NEAR · illustrative configuration.<br>USD market value is approximate.</p>`;}
function terms(){return`<details><summary>Match rules & cancellation</summary><div class="detail-content">First to deliver 12 iron, 6 copper and 8 asphalt wins. Demo rules: equal starts, x1 speed, no personal pause. The future game server determines the result; escrow does not calculate gameplay.<br><br>Before start: locked stakes are refunded in USDC on NEAR. No game fee on cancellation or draw. Swap/network costs already spent are not refundable by the game. No automatic reverse swap.<br><br>Draw, disconnection and server interruption policies are proposed for UI review. They are not approved contract behavior.</div></details>`;}
function home(){return`<section class="hero"><div class="hero-image" role="img" aria-label="Supply Line alpine game map"></div><div class="hero-copy"><div class="eyebrow">A race of supply & strategy</div><h1>Build the line.<br>Win the race.</h1><p>Two supply chains. One finish line. Deliver your resources before your opponent does.</p><div class="hero-tags">${pill('1v1 strategy')}${pill('Equal starting conditions')}${pill('12 / 6 / 8 to win')}</div></div><section class="card home-menu"><h2>Choose your route</h2><button class="mode primary" data-action="online"><span class="icon-disc" aria-hidden="true">${SupplyLineMenuIcon('online')}</span><span>Play online<small>Create a lobby. Invite a friend.</small></span><span class="arrow" aria-hidden="true">→</span></button><button class="mode" data-action="tutorial"><span class="icon-disc" aria-hidden="true">${SupplyLineMenuIcon('tutorial')}</span><span>Play tutorial<small>Learn the supply chain.</small></span><span class="arrow" aria-hidden="true">→</span></button><button class="mode" data-action="bot"><span class="icon-disc" aria-hidden="true">${SupplyLineMenuIcon('bot')}</span><span>Race the bot<small>Practice without a wallet.</small></span><span class="arrow" aria-hidden="true">→</span></button><div class="home-sub"><span aria-hidden="true">◇</span><p><strong>${gameAvailable?'Choose your game':'Interface preview'}</strong><br>${gameAvailable?'Tutorial and bot race are playable. Online wallets, stakes and matches use demonstration data.':'All online steps are simulated. Tutorial and bot are entry-point previews here.'}</p></div></section></section>`;}
function online(){return shell(`${back('home')}${heading('Multiplayer','Your next race starts here.','Invite a friend to a 1v1 match. Review the same terms before either player locks a stake.',pill('Demo environment','warn'))}${activeMatch()||hasObligation()?`<div class="strip"><div><strong>${state.match?'You have a demo match to continue':'You have a demo top-up to check'}</strong><p>${esc(state.match?.id||'Wallet funding')} · operations stay linked to ${esc(account())}</p></div>${button('Resume match','resume','primary')}</div>`:''}<div class="online-cards"><section class="card"><span class="icon-disc" aria-hidden="true">＋</span><h2>Create a lobby</h2><p>Choose an equal stake and send a private invitation.</p>${button('Create lobby','create','primary')}</section><section class="card"><span class="icon-disc" aria-hidden="true">↗</span><h2>Join a friend</h2><p>Open an invite link or enter a lobby code.</p>${button('Join with link / code','join')}</section><section class="card"><span class="icon-disc" aria-hidden="true">≡</span><h2>My matches</h2><p>Return to a match, check a transfer or follow a refund.</p>${button('View my matches','matches')}</section></div><div class="strip"><div><strong>Want to fund your wallet first?</strong><p>Preview an Intents conversion before the 10-minute lobby timer starts.</p></div>${button('Preview wallet funding','prefund')}</div>${notice('Demonstration assumptions','USDC on NEAR, sample source assets and a 3% game fee are proposed UI settings. Routes, rates, limits and fees are fictional; no supported assets are confirmed.')}`);}
function create(){return shell(`${back()}${heading('New 1v1 match','Create a lobby','Set the stake both players will confirm. Terms become fixed before funding.')}<div class="grid"><section class="card"><h2>Match settings</h2><form id="createForm" novalidate><label for="stakeAmount">Stake per player</label><div class="amount-wrap"><span class="currency-prefix" aria-hidden="true">$</span><input id="stakeAmount" name="stake" inputmode="decimal" autocomplete="off" aria-describedby="stakeHelp stakeError" aria-invalid="${!!state.error}" value="${esc(state.amount)}"></div><div class="preset">${['5.00','10.00','25.00'].map(v=>`<button type="button" data-amount="${v}" class="${state.amount===v?'selected':''}">$${v}</button>`).join('')}</div><p id="stakeHelp" class="help">$5.00 means 5.00 USDC. Demo range: 1–100 USDC, up to 2 decimals.</p><p id="stakeError" class="field-error" role="alert">${esc(state.error)}</p><div class="notice"><strong>Settled in USDC on NEAR</strong><p>Choose a different source asset when funding. Both stakes are always the same exact USDC amount.</p></div><ol class="number-list"><li>Create a private lobby and share the invitation.</li><li>Both players confirm terms and lock equal stakes.</li><li>Be first to supply the hub: 12 iron, 6 copper, 8 asphalt.</li></ol><button type="submit" class="primary full">${state.wallet?'Create lobby':'Connect wallet & create lobby'}</button></form></section><aside class="card flat"><h2>Before you commit</h2><div id="createSummary">${financials()}</div>${notice('Example fee, not an approved tariff','3% and fee recipient supply-line-fee.demo.near are fictional and fixed for this demo match. No additional app fee on conversion.')}${terms()}</aside></div>`);}
function join(){return shell(`${back()}${heading('Invitation','Join a friend','Review match terms before connecting or paying.')}<div class="grid"><section class="card"><h2>Enter an invitation</h2><form id="joinForm" novalidate><label for="joinCode">Lobby code or invite link</label><input id="joinCode" value="${esc(state.joinCode)}" autocomplete="off" placeholder="SL-DEMO-42" aria-describedby="joinHelp joinError"><p id="joinHelp" class="help">Try SL-DEMO-42. This invitation opens a local demo only.</p><p id="joinError" class="field-error" role="alert">${esc(state.error)}</p><button type="submit" class="primary full">Review lobby</button></form></section><aside class="card flat"><h2>A fair start</h2><p>An invitation does not connect your wallet or authorize a transaction. You will see the opponent, stake and prize before joining.</p>${terms()}</aside></div>`);}
function joinReview(){return shell(`${back()}${heading('Private invitation · SL-DEMO-42','You’re invited.','Riley is waiting for a challenger. No payment has been requested.')}<div class="grid"><section class="card"><div class="player"><div class="avatar rival">R</div><div class="player-info"><div class="player-name">Riley · host</div><div class="player-account">riley.demo.near</div></div>${pill('Seat available','good')}</div>${financials(true,5000000n)}${notice('Demo invitation','All accounts and terms are fictional. Joining will reserve the second seat in this browser only.')}<div class="actions">${button(state.wallet?'Join lobby':'Connect wallet & join','accept-invite','primary full')}</div>${terms()}</section><aside class="card flat"><h2>What happens next?</h2><ol class="number-list"><li>Connect a demo NEAR account.</li><li>Choose a source asset and confirm the quote.</li><li>Confirm your stake as a separate step.</li></ol><p class="small">Lobby expires in <span class="timer">10:00</span>. If a conversion finishes after expiry, USDC stays in your wallet.</p></aside></div>`);}
function stepper(){const m=state.match;let n=!m.opponent?0:state.deposit!=='locked'||!m.opponentLocked?1:m.status==='active'?3:2;return`<ol class="stepper">${['Opponent','Funding','Ready','Match'].map((t,i)=>`<li class="${i<n?'done':i===n?'current':''}"><b>${i<n?'✓':i+1}</b>${t}</li>`).join('')}</ol>`;}
function playerCard(rival=false){const m=state.match,connected=!!m.opponent;const status=rival?(!connected?'Waiting for opponent':m.opponentLocked?'✓ Stake locked · Ready':'Wallet connected · awaiting funding'):state.deposit==='locked'?'✓ Stake locked · Ready':state.deposit==='pending'?'Awaiting stake confirmation':state.swap==='pending'?'Converting funds':state.swap==='completed'?'Swap completed · stake not locked':'Wallet connected';return`<div class="player ${rival&&!connected?'waiting':''}"><div class="avatar ${rival?'rival':''}">${rival?(connected?'R':'?'):'A'}</div><div class="player-info"><div class="player-name">${rival?(connected?'Riley':'Open seat'):'You'}</div><div class="player-account">${esc(rival?(m.opponent||'Share the private invitation'):m.account)}</div><div class="player-status">${status}</div></div>${pill(rival&&!connected?'Waiting':((rival?m.opponentLocked:state.deposit==='locked')?'Ready':'Not ready'),(rival?m.opponentLocked:state.deposit==='locked')?'good':'')}</div>`;}
function invitation(){const url=location.href.split('#')[0]+'#join=SL-DEMO-42';return`<label for="inviteLink">Private invitation</label><div class="row copy-row"><input id="inviteLink" readonly value="${esc(url)}">${button('Copy invite','copy')}</div><p class="help">Code: <strong>SL-DEMO-42</strong> · Demo link. No signing permissions.</p>`;}
function sourceAmount(){const a=amounts(),s=sources[state.source],cost=state.source==='usdc'?0n:150000n;return{max:(a.stake+cost)*BASE/s.unit,cost};}
function sourceForm(){const s=sources[state.source];return`<label for="sourceAsset">Pay with</label><select id="sourceAsset" ${state.swap==='pending'||state.deposit==='pending'||state.swap==='completed'||state.swap==='unknown'?'disabled':''}>${Object.entries(sources).map(([k,v])=>`<option value="${k}" ${state.source===k?'selected':''}>${v.name} · ${v.network} (demo)</option>`).join('')}</select><p class="help">Demo balance: ${money(state.balances[s.balanceKey],s.places)} ${s.name}<br>${s.description}</p>`;}
function quote(){const {stake}=amounts(),s=sources[state.source],q=sourceAmount(),expired=state.quoteStatus==='expired'||Date.now()>=state.quoteUntil;return`<div class="quote"><div class="quote-head"><strong>Exact-output demo quote</strong>${pill(expired?'Quote expired':'Valid · '+Math.max(0,Math.ceil((state.quoteUntil-Date.now())/1000))+'s',expired?'error':'good')}</div><dl class="ledger"><div><dt>Stake received in your wallet</dt><dd>${money(stake)} USDC · NEAR</dd></div><div><dt>Swap/network costs</dt><dd>≈ ${money(q.cost)} USDC</dd></div><div><dt>Maximum you pay</dt><dd>${money(q.max,s.places)} ${s.name}</dd></div></dl><p class="small no-margin">Fictional rate: 1 ${s.name} ≈ $${money(s.unit)}. This is not a live quote.</p></div>`;}
function paymentDetails(){const m=state.match;return`<details><summary>Payment details</summary><div class="detail-content">Demo quote ID: DEMO-QUOTE-42<br>Route: ${sources[state.source].name} on ${sources[state.source].network} → USDC on NEAR<br>Recipient & swap refund account: ${esc(account())}<br>Escrow stake recipient: escrow.demo.near (fictional)<br>Game fee recipient: supply-line-fee.demo.near (fictional)<br>Sample gas + storage + route costs: ≈ 0.15 USDC for conversion; no additional app fee. Maximum spend includes a fictional route buffer. A live implementation must quote gas/storage separately before signing.<br>Quote lifetime: 60 seconds. Conversion estimate: 1–3 minutes (illustrative).<br>Swap completion is independent from stake acceptance.${m?'<br>Match: '+esc(m.id)+' · terms v1 · rules 12/6/8 · map v31 demo snapshot':''}<br>There is no real deposit address, memo, contract or transaction link in this prototype.</div></details>`;}
function paymentError(){const messages={route:['Route unavailable','This demo route cannot fill the exact stake. Choose another asset or network; your stake has not changed.'],balance:['Insufficient balance','Your demo balance cannot cover the maximum payment and network reserve. Choose another asset.'],network:['Wrong payment network','This demo route expects Ethereum. Switch the simulated payment wallet to Ethereum.'],signature:['Transaction cancelled','You declined the simulated signature. No new demo funds were moved. Try again when ready.'],swap:['Conversion failed','The simulated route failed before funds were sent. Get a new quote.'],deposit:['Deposit not accepted','The demo escrow resolver returned the full stake to your NEAR wallet. It is not locked. Review terms and confirm again.'],account:['Wrong account','This match belongs to '+esc(account())+'. Reconnect that demo account to continue.']};const m=messages[state.error];return m?notice(m[0],m[1],'error')+(state.error==='network'?button('Switch demo payment network','fix-network','compact-link'):''):state.error?notice(esc(state.error),'','error'):'';}
function payment(prefund=false){const m=state.match,locked=state.deposit==='locked',converted=state.swap==='completed';let body='';
 if(!sameAccount()&&!prefund)return notice('Account changed',`This match is bound to ${esc(account())}. Your stake and rights have not moved to the newly connected account.`,'error')+button('Reconnect match account','restore-account','primary full spaced');
 if(locked)return notice('✓ Stake locked',`${money(amounts().stake)} USDC is reserved for this match. Your wallet is connected and your stake is ready.`,'good')+button('View demo transaction','receipts','compact-link');
 body=`<div class="payment-step-title"><span class="step-dot">1</span><h3>Convert funds</h3></div>`+sourceForm()+paymentError();
 if(state.swap==='pending')body+=wait('Converting funds','Demo conversion in progress. Closing this panel does not cancel a submitted transfer. No stake is locked yet.')+button('View conversion activity','receipts','compact-link');
 else if(state.swap==='unknown')body+=notice('Conversion status unknown','Check this operation before starting another conversion. Your demo balance will only be updated once.','error')+button('Check conversion status','check-swap','primary full spaced');
 else if(state.swap==='refund-pending')body+=wait('Swap refund pending','This is a refund from the conversion route, not an escrow refund. Original source asset; network costs may remain.')+button('Check swap refund','check-swap-refund','full spaced');
 else if(state.swap==='refunded')body+=notice('Swap refund confirmed','Demo source funds returned in NEAR. No stake was accepted; no game fee was charged.','good')+button('Get a new quote','quote','primary full spaced');
 else if(converted)body+=notice('✓ Swap completed',`${money(amounts().stake)} USDC is in ${esc(account())}. It is not locked in escrow.`,'good');
 else if(state.source==='usdc')body+=notice('USDC is already in your NEAR wallet','Conversion is not needed. Stake confirmation is still a separate action.','good')+`<dl class="ledger"><div><dt>Swap/network costs · demo</dt><dd>0.00 USDC</dd></div><div><dt>Maximum you pay</dt><dd>${money(amounts().stake)} USDC</dd></div></dl>`;
 else if(state.quoteStatus==='valid'||state.quoteStatus==='expired'){body+=quote()+button(state.quoteStatus==='expired'?'Get new quote':'Convert funds',state.quoteStatus==='expired'?'quote':'convert','primary full spaced');}
 else body+=button(state.paymentConnected||state.source!=='eth'?'Get quote':'Connect payment wallet',state.paymentConnected||state.source!=='eth'?'quote':'payment-wallet','primary full spaced');
 if(!prefund){body+=`<div class="payment-step"><span class="step-dot">2</span><div class="step-body"><h3>Confirm stake</h3><p>Separate from conversion. Lock exactly ${money(amounts().stake)} USDC for this match.</p>`;
 if(state.deposit==='pending')body+=wait('Awaiting stake confirmation','The demo wallet approved the request. Waiting for final escrow acceptance; the match cannot start.');
 else if(state.deposit==='unknown')body+=notice('Stake status unknown','Check final escrow acceptance before retrying. No duplicate confirmation is available.','error')+button('Check stake status','check-deposit','primary full');
 else body+=button('Confirm stake','confirm-stake','primary full',(!converted&&state.source!=='usdc')||['pending','unknown','refund-pending'].includes(state.swap)||state.swap==='refunded');
 body+='</div></div>';
 }else if(converted||state.source==='usdc')body+=button('Return to Play online','online','primary full spaced');
 return body+paymentDetails();}
function lobby(){if(!state.match)return online();const m=state.match,expired=m.status==='expired',cancelled=m.status==='cancelled';if(expired||cancelled)return terminalLobby();const ready=state.deposit==='locked'&&m.opponentLocked;
 return shell(`${back()}${heading('Private lobby · '+esc(m.id),'The route is set.','Share the invitation. Both stakes must be accepted before the race starts.',`<div>${pill('Demo lobby','warn')}<p class="small spaced">Expires in <span data-timer="lobby" class="timer">${remaining()}</span></p></div>`)}${stepper()}<div class="grid"><div><section class="card"><div class="card-title"><h2>Drivers</h2>${pill('1v1 · private')}</div>${playerCard()}${playerCard(true)}${!m.opponent?invitation():`<p class="small spaced">Both players accepted terms v1 · stake is now fixed.</p>`}${!m.opponent?`<div class="actions">${button('Add demo opponent','add-opponent','ghost')}</div>`:''}${ready?notice('✓ Both players ready','Both demo stakes are locked. Waiting for the match process before a synchronized 3-second countdown.','good'):''}${m.status==='starting'?wait('Starting match','Both demo deposits are accepted. Countdown: <strong data-countdown>3</strong>.'):''}${ready&&m.status!=='starting'?button('Start demo countdown','start','primary full spaced'):''}<div class="actions">${button('Cancel lobby','cancel-lobby','ghost danger',m.status==='starting')}${button('Match details','details','ghost')}</div></section><section class="card flat"><h2>Match terms</h2>${financials()}${terms()}</section></div><aside class="card"><div class="card-title"><h2>Your stake</h2>${pill('Demo data','warn')}</div>${!m.opponent?`<p>Waiting for opponent. Funding opens after both players accept the same terms.</p>${notice('You have not paid anything','You can cancel this invitation or preview wallet funding before your next lobby.')}`:payment()}${state.deposit==='locked'&&!m.opponentLocked?`<div class="actions">${button('Fund demo opponent','fund-opponent','full')}</div>`:''}</aside></div>`);}
function remaining(){const n=Math.max(0,Math.ceil(((state.match?.deadline||Date.now())-Date.now())/1000));return`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function terminalLobby(){const expired=state.match.status==='expired',locked=state.deposit==='locked',unresolved=['pending','unknown'].includes(state.deposit);return shell(`${back()}${heading('Private lobby · '+esc(state.match.id),expired?'Lobby expired':'Lobby cancelled',expired?'The 10-minute invitation window has ended. No match will start.':'This match will not start. Follow any remaining refund below.')}<div class="grid"><section class="card">${notice(expired?'Lobby expired':'Cancellation confirmed',unresolved?'A stake request is unresolved. Check the existing deposit before assuming it was accepted or returned.':locked?'Your stake was locked. It is now eligible for an escrow refund in USDC on NEAR. No game fee is charged.':state.swap==='completed'?'The conversion completed, but no stake was locked. USDC remains in your personal NEAR wallet. There is no automatic reverse conversion.':'No stake was accepted. You have no escrow funds to recover.',locked?'':'good')}${state.swap==='pending'||state.swap==='unknown'?notice('Conversion still needs checking','Lobby expiry does not cancel a submitted conversion. Its output must stay in your wallet, not be deposited into another match.')+button('Check conversion status','check-swap','primary spaced'):''}${unresolved?notice('Stake status unknown','Reconcile the existing deposit. Do not submit it again.','error')+button('Check stake status','check-deposit','primary full spaced'):''}${locked?refundPanel():''}<div class="actions">${button('Create a new lobby','new-lobby','primary',hasObligation())}${button('My matches','matches')}</div></section><aside class="card flat">${financials()}<p class="small">Conversion and network costs already spent are separate from the game stake refund.</p></aside></div>`);}
function progress(name,rival=false){const p=rival?state.match.rivalProgress:state.match.progress;return`<div class="progress-player"><div class="row between"><strong>${name}</strong><span>${p}%</span></div><div class="bar ${rival?'rival':''}"><span style="width:${p}%"></span></div><p class="small spaced">Iron ${Math.floor(12*p/100)}/12 · Copper ${Math.floor(6*p/100)}/6 · Asphalt ${Math.floor(8*p/100)}/8</p></div>`;}
function match(){return shell(`${heading('Online race · '+esc(state.match.id),'Supply the hub.','Scripted match preview on the existing Supply Line map. Gameplay controls are not connected.')}${state.connection==='disconnected'?notice('Connection lost · reconnecting','Demo recovery window: 120 seconds. The scripted clock continues. The future server match would not pause.','error')+button('Restore demo connection','reconnect','spaced'):''}${!sameAccount()?notice('Account changed','Reconnect '+esc(account())+' to access match actions. Match ownership has not moved.','error')+button('Reconnect match account','restore-account','spaced'):''}<div class="match-strip"><div><small>Opponent</small><br><strong>${esc(state.match.opponent)}</strong></div><div><small>Stake</small><br><strong>${money(amounts().stake)} USDC</strong></div><div><small>Winner receives</small><br><strong>${money(amounts().prize)} USDC</strong></div><span class="clock" data-clock>${clock()}</span>${pill(state.connection==='connected'?'✓ Demo connection':'! Reconnecting',state.connection==='connected'?'good':'error')}${button('Match details','details','ghost')}</div><div class="game-layout"><div class="map-preview" role="img" aria-label="Static preview of the current Supply Line map"><div class="map-caption">Existing game map · static preview. Progress and results below are simulated.</div></div><aside class="match-side"><section class="card"><h2>Delivery progress</h2>${progress('You')}${progress('Riley',true)}</section><section class="card flat"><h3>Demo match controls</h3><p class="small">Jump to a result to review settlement. These buttons are only for this prototype.</p><div class="actions stacked">${button('Preview win','win','primary')}${button('Preview loss','lose')}${button('Preview draw','draw')}${button('Surrender','surrender','ghost danger',!sameAccount())}</div></section></aside></div>`);}
function clock(){const n=state.match?.time||0;return`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function payoutPanel(){let html='';const paid=state.payout==='confirmed',lost=state.outcome==='lost',receiver=lost?state.match.opponent:account();
 if(state.payout==='pending')html=wait('Payout pending','The demo result is recorded. The prize transfer has not been sent yet.')+button('Send demo payout','send-payout','primary full spaced');
 if(state.payout==='sent')html=wait('Payout sent','A demo transfer is in flight. Final callback is not confirmed. Do not send another payout.')+button('Check payout status','check-payout','full spaced');
 if(state.payout==='unknown')html=notice('Payout status unknown','Reconcile the transfer before retrying. It may already have been sent.','error')+button('Check payout status','check-payout','primary full spaced');
 if(state.payout==='error')html=notice('Action required','Demo receiver storage registration failed. The prize remains owed to the same account.','error')+button('Resolve demo storage & retry','retry-payout','primary full spaced');
 if(paid)html=notice(lost?'✓ Winner payout confirmed':'✓ Payout confirmed',`${money(amounts().prize)} USDC → ${esc(receiver)} on NEAR.`,'good');
 html+=`<dl class="ledger"><div><dt>Prize recipient</dt><dd class="account">${esc(receiver)}</dd></div><div><dt>Settlement token / network</dt><dd>USDC / NEAR · demo</dd></div><div><dt>Game fee transfer</dt><dd>${state.feePayout==='confirmed'?'✓ Confirmed':state.feePayout==='pending'?'Pending · separate transfer':'Not sent'}</dd></div><div><dt>Match status</dt><dd>${paid&&state.feePayout==='confirmed'?'Completed':'Settlement pending'}</dd></div></dl>`;
 if(paid&&state.feePayout==='pending')html+=notice('Prize is paid; settlement is still pending','The separate game fee transfer has not confirmed. The prize will not be sent again.')+button('Check game fee transfer','check-fee','full spaced');
 return html+button('View demo transactions','receipts','compact-link');}
function refundPanel(){const status=state.refund;let html='';if(status==='pending')html=wait('Refund pending',`Your ${money(amounts().stake)} USDC stake is owed to ${esc(account())}. No game fee applies.`)+button('Send demo refund','send-refund','primary full spaced');if(status==='sent')html=wait('Refund sent','Demo transfer in flight. Waiting for final callback; do not request a duplicate.')+button('Check refund status','check-refund','full spaced');if(status==='unknown')html=notice('Refund status unknown','Check the existing transfer before retrying.','error')+button('Check refund status','check-refund','primary full spaced');if(status==='error')html=notice('Action required','The demo refund transfer failed. Resolve receiver storage before retrying.','error')+button('Resolve demo storage & retry','retry-refund','primary full spaced');if(status==='confirmed')html=notice('✓ Refund confirmed',`${money(amounts().stake)} USDC returned to ${esc(account())} on NEAR. No reverse swap; previous swap/network costs are separate.`,'good');return html+button('View demo transactions','receipts','compact-link');}
function result(){const isRefund=['draw','interrupted'].includes(state.outcome),title={won:'You won',lost:'You lost',draw:'Draw',interrupted:'Match interrupted'}[state.outcome],reason={won:'You delivered 12 iron, 6 copper and 8 asphalt first.',lost:'Riley completed the hub order first.',draw:'Both players finished in the same scripted tick.',interrupted:'The demo server could not restore a verifiable result.'}[state.outcome];return shell(`${back()}${heading('Match result · '+esc(state.match.id),'Race finished.','Game outcome and money transfer confirmation are separate events.')}<div class="grid"><section class="card result-card"><div class="result-emblem" aria-hidden="true">${state.outcome==='won'?'⚑':state.outcome==='lost'?'↗':'='}</div><h2 class="result-title">${title}</h2><p>${reason}</p>${pill('Scripted demo result','warn')}<hr class="separator">${isRefund?`<dl class="ledger"><div><dt>Stake refunded per player</dt><dd>${money(amounts().stake)} USDC</dd></div><div><dt>Game fee</dt><dd>0.00 USDC</dd></div></dl><p class="small">Proposed ${state.outcome==='draw'?'draw':'server interruption'} rule for review. Contract compatibility is not implemented.</p>`:financials()}<div class="actions">${button('My matches','matches','primary')}${button('Play online','online')}</div><p class="small spaced">In the future system, the game server submits the result. Escrow does not verify the delivery goal.</p></section><aside class="card"><div class="card-title"><h2>${isRefund?'Stake refund':'Settlement'}</h2>${pill('Demo ledger')}</div>${isRefund?refundPanel():payoutPanel()}</aside></div>`);}
function history(){const entries=[];if(state.match)entries.push({id:state.match.id,status:state.match.status,stake:state.match.stake,detail:state.refund!=='idle'?'Refund '+state.refund:state.payout!=='idle'?'Payout '+state.payout:state.swap==='pending'||state.swap==='unknown'?'Conversion '+state.swap:state.deposit==='locked'?'Stake locked':state.swap==='completed'?'Swap completed · stake not locked':'Waiting / funding',current:true});entries.push(...state.history);const filtered=entries.filter(x=>state.tab==='all'||(state.tab==='active'?!['completed','cancelled','expired'].includes(x.status):['completed','cancelled','expired'].includes(x.status)));return shell(`${back()}${heading('Your activity','My matches','Resume the current demo match and inspect unfinished conversions, deposits, payouts or refunds.')}${state.wallet?`<p class="small account">Demo account: ${esc(state.wallet)}</p>`:notice('No demo wallet connected','You can review this browser’s demo history. Connect the original match account to continue financial actions.')}<div class="tabs" role="tablist" aria-label="Match filter">${[['all','All matches'],['active','Active'],['finished','Finished']].map(([k,v])=>`<button role="tab" aria-selected="${state.tab===k}" data-tab="${k}">${v}</button>`).join('')}</div><div class="history-list">${filtered.length?filtered.map(x=>`<article class="history-item"><div class="history-summary"><h3>${esc(x.id)}</h3><p>${esc(x.detail)} · ${money(x.stake)} USDC stake</p></div>${pill(esc(x.status),x.status==='completed'?'good':'')}${button(x.current?'Open match':'View receipt',x.current?'resume':'archive-'+x.id,'ghost')}</article>`).join(''):`<div class="card empty"><h2>No ${state.tab==='all'?'demo':state.tab} matches yet</h2><p>Create a private lobby to try the flow.</p>${button('Create lobby','create','primary')}</div>`}</div>${state.swap==='pending'||state.swap==='unknown'||state.swap==='refund-pending'?notice('Unfinished conversion','Open the current match to check the existing operation. A new payment will not be sent automatically.'):''}<p class="small spaced">History is stored under a separate demo-only browser key. It never reads or changes game saves.</p>`);}
function prefund(){return shell(`${back()}${heading('Before your next lobby','Fund your demo NEAR wallet','Convert first, create the lobby later. This avoids spending a lobby’s 10-minute window on conversion.')}<div class="grid"><section class="card"><h2>Preview a ${money(amounts().stake)} USDC top-up</h2>${state.wallet?payment(true):notice('Connect a demo NEAR account','This will be the recipient of the simulated conversion.')+button('Connect demo wallet','wallet','primary full spaced')}</section><aside class="card flat"><h2>Two distinct steps</h2><ol class="number-list"><li>Convert into USDC in your personal NEAR account.</li><li>Later, confirm a stake for a specific lobby.</li></ol><p>No funds are locked in escrow during this preview. You can keep USDC in your demo wallet even if you never join a match.</p></aside></div>`);}
function render(focus=false){save();const pages={home,online,create,join,'join-review':joinReview,lobby,match,result,matches:history,prefund};$('#app').innerHTML=(pages[state.page]||home)();$('#walletButton').textContent=state.wallet?state.wallet.length>22?state.wallet.slice(0,11)+'…'+state.wallet.slice(-7):state.wallet+' · DEMO':'Connect wallet';$('#walletButton').classList.toggle('wallet-connected',!!state.wallet);$('#walletButton').setAttribute('aria-label',state.wallet?'Demo wallet '+state.wallet:'Connect wallet');for(const b of document.querySelectorAll('.app-header nav button'))b.classList.toggle('active',b.dataset.action==='matches'?state.page==='matches':!['home','matches'].includes(state.page));if(focus){$('#app').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});} }
function openModal(title,html){focusedBefore=document.activeElement;$('#modal').innerHTML=`<div class="dialog-head"><h2 id="modalTitle">${title}</h2>${button('×','close-modal','close')}</div><div class="notice modal-demo"><strong>DEMO ONLY</strong> · No real accounts, signatures or transfers.</div>${html}`;$('#modal').querySelector('.close').setAttribute('aria-label','Close dialog');if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();if(focusedBefore?.isConnected)focusedBefore.focus();}
function walletModal(next=null){modalReturn=next;if(state.wallet){openModal('Demo wallet',`<div class="row"><span class="icon-disc">◇</span><div><strong class="account">${esc(state.wallet)}</strong><p class="small no-margin">NEAR · simulated network</p></div></div><dl class="ledger"><div><dt>USDC balance</dt><dd>${money(state.balances.usdc)} USDC</dd></div><div><dt>Account connection</dt><dd>Demo only</dd></div></dl><p class="small">A real backend would verify a separate signed login challenge.</p><div class="actions stacked">${button('Switch to another demo account','switch-account')}${button('Disconnect demo wallet','disconnect','danger')}${button('View transaction activity','receipts')}</div>`);}else openModal('Connect wallet',`<p>Choose a fictional NEAR account for this prototype. No wallet extension will open.</p><button class="wallet-option" data-action="connect"><span class="icon-disc">◇</span><span>Demo NEAR account<small>alex.demo.near · local simulation</small></span><span aria-hidden="true">→</span></button><p class="small">Payment wallets in other networks are connected separately during funding.</p><div class="actions">${button('Simulate connection error','wallet-error','ghost')}${button('Cancel connection','close-modal','ghost')}</div>`);}
function stakeModal(){if(!state.wallet||!sameAccount()){state.error='account';return render();}if(state.deposit!=='idle'||!state.match?.opponent||state.match.status!=='funding')return;if(BigInt(state.balances.usdc)<amounts().stake){state.error='balance';return render();}openModal('Confirm your stake',`<p>You are locking <strong>${money(amounts().stake)} USDC</strong> for this match.</p><dl class="ledger"><div><dt>Opponent</dt><dd>${esc(state.match.opponent)}</dd></div><div><dt>Stake · USDC on NEAR</dt><dd>${money(amounts().stake)}</dd></div><div><dt>Game fee · sample 3%</dt><dd>${money(amounts().fee)} USDC</dd></div><div><dt>Winner receives</dt><dd>${money(amounts().prize)} USDC</dd></div></dl>${notice('Before the start','A cancelled or expired match refunds the locked stake in USDC on NEAR. Prior swap/network costs are separate. No reverse conversion.')}<p class="small spaced">Match ${esc(state.match.id)} · terms v1 · fee receiver supply-line-fee.demo.near · illustrative configuration</p><div class="actions stacked">${button('Confirm demo stake','submit-stake','primary')}${button('Decline signature','decline-stake','ghost')}${button('Back to lobby','close-modal','ghost')}</div>`);}
function receipts(){openModal('Demo transaction activity',`<p class="small">Generated receipt identifiers; these are not blockchain hashes or explorer links.</p><div class="receipt">${state.events.length?state.events.map(e=>`<article class="receipt-item"><strong>${esc(e.type)}</strong><p class="mono">${esc(e.id)}</p><p class="small">${esc(e.detail)}</p><time class="small">${esc(e.time)}</time></article>`).join(''):'<p>No simulated transactions yet.</p>'}</div>`);}
function begin(kind,delay=2200){if(state.pending)return;state.pending={kind};if(kind==='swap'){state.swap='pending';record('Conversion submitted','Demo route to personal NEAR wallet; not a stake.');}if(kind==='deposit'){state.deposit='pending';record('Stake submitted','Awaiting final escrow acceptance.');}if(kind==='payout'){state.payout='sent';record('Payout sent','Demo prize transfer in flight.');}if(kind==='refund'){state.refund='sent';record('Refund sent','Demo USDC refund transfer in flight.');}if(kind==='countdown'){state.match.status='starting';state.pending.count=3;state.pending.endsAt=Date.now()+3000;}save();render();if(!state.hold)timer=setTimeout(resolvePending,delay);}
function acceptSwap(){if(state.swap==='completed')return;const q=sourceAmount();if(BigInt(state.balances[sources[state.source].balanceKey])<q.max){state.swap='idle';state.error='balance';return;}state.balances[sources[state.source].balanceKey]=String(BigInt(state.balances[sources[state.source].balanceKey])-q.max);state.balances.usdc=String(BigInt(state.balances.usdc)+amounts().stake);state.swap='completed';record('Swap completed',`${money(amounts().stake)} USDC in personal NEAR wallet; stake not locked.`);}
function acceptDeposit(){if(state.deposit==='locked')return;if(!state.match||['expired','cancelled'].includes(state.match.status)){state.deposit='idle';record('Deposit not accepted','Expired/cancelled demo lobby; resolver returned the stake to your NEAR wallet.');return;}if(BigInt(state.balances.usdc)<amounts().stake){state.deposit='idle';state.error='balance';return;}state.balances.usdc=String(BigInt(state.balances.usdc)-amounts().stake);state.deposit='locked';record('Stake locked','Demo final escrow acceptance; exact USDC amount.');if(state.match.opponentLocked)state.match.status='ready';}
function acceptPayout(){if(state.payout==='confirmed')return;state.payout='confirmed';if(state.outcome==='won')state.balances.usdc=String(BigInt(state.balances.usdc)+amounts().prize);state.feePayout='confirmed';state.match.status='completed';record('Payout confirmed','Demo prize and separate game fee callbacks confirmed.');}
function acceptRefund(){if(state.refund==='confirmed')return;state.refund='confirmed';state.balances.usdc=String(BigInt(state.balances.usdc)+amounts().stake);record('Refund confirmed','Demo stake returned in USDC; no game fee.');if(state.match.status!=='expired')state.match.status='cancelled';}
function resolvePending(){if(!state.pending)return;const k=state.pending.kind;clearPending();if(k==='swap')acceptSwap();if(k==='deposit')acceptDeposit();if(k==='payout')acceptPayout();if(k==='refund')acceptRefund();if(k==='countdown'){state.match.status='active';state.page='match';state.match.time=0;}render();}
function archive(){if(!state.match)return;state.history.unshift({id:state.match.id+'-'+String(state.history.length+1),stake:state.match.stake,status:state.match.status,detail:state.refund!=='idle'?'Refund '+state.refund:state.payout!=='idle'?'Payout '+state.payout:'Lobby closed',events:state.events.slice()});state.history=state.history.slice(0,20);state.match=null;}
function createLobby(){if(activeMatch()||hasObligation()){go('lobby');return toast('Finish or cancel the current demo match first.');}archive();mkMatch();go('lobby');}
function finish(outcome){if(state.match?.status!=='active')return;clearPending();state.outcome=outcome;state.match.status='settlement';state.page='result';if(['draw','interrupted'].includes(outcome))state.refund='pending';else{state.payout='pending';state.feePayout='pending';}record('Demo result recorded',outcome+'; transfer not confirmed.');render(true);}
function resume(){if(!state.match)return go(['pending','unknown','refund-pending'].includes(state.swap)?'prefund':'online');state.page=state.match.status==='active'?'match':['settlement','completed'].includes(state.match.status)?'result':'lobby';render(true);}
function expire(){if(!state.match||!['open','funding','ready','starting'].includes(state.match.status))return;state.match.status='expired';state.match.deadline=Date.now()-1;if(state.deposit==='locked')state.refund='pending';if(state.pending?.kind==='countdown'||state.pending?.kind==='deposit'){clearPending();if(state.deposit==='pending')state.deposit='unknown';}record('Lobby expired','No automatic transfer into another match.');if(state.page==='lobby')render();else save();}
function loadScenario(key){clearPending();clearTimeout(toastTimer);$('#toast').hidden=true;closeModal();if($('#lab').open)$('#lab').close();state=fresh();state.wallet='alex.demo.near';state.hold=true;resumed=false;if(key==='home'){state.wallet=null;render(true);return;}if(key==='create'){state.page='create';render(true);return;}mkMatch(key!=='waiting');state.page='lobby';if(key==='waiting'){render(true);return;}if(key==='full'||key==='self-join'){state.match=null;state.page='join-review';state.note=key;render(true);toast(key==='full'?'Lobby is full. No payment was requested.':'You are already in this lobby. One account cannot occupy both seats.');return;}
 state.quoteStatus='valid';state.quoteUntil=Date.now()+60000;
 const errors={'no-route':'route','low-balance':'balance','wrong-network':'network','cancelled-signature':'signature','swap-failed':'swap','deposit-rejected':'deposit'};
 if(errors[key]){state.error=errors[key];state.quoteStatus='idle';}
 if(key==='low-balance')state.balances.near='100000';if(key==='wrong-network')state.source='eth';
 if(key==='quote-expired'){state.quoteStatus='expired';state.quoteUntil=Date.now()-1;}
 if(key==='converting')begin('swap');if(key==='swap-unknown')state.swap='unknown';if(key==='swap-refund')state.swap='refund-pending';if(key==='swap-refunded')state.swap='refunded';
 const converted=['converted','awaiting-deposit','deposit-rejected','deposit-unknown','locked','ready','starting','expired','expired-locked','active','disconnected','account-changed','won','lost','draw','payout-sent','payout-error','payout-unknown','payout-confirmed','fee-pending','cancel-refund','refund-error','refund-sent','refund-confirmed','server-refund','matches'];
 if(converted.includes(key))acceptSwap();if(key==='awaiting-deposit')begin('deposit');if(key==='deposit-unknown')state.deposit='unknown';
 const deposited=['locked','ready','starting','expired-locked','active','disconnected','account-changed','won','lost','draw','payout-sent','payout-error','payout-unknown','payout-confirmed','fee-pending','cancel-refund','refund-error','refund-sent','refund-confirmed','server-refund','matches'];
 if(deposited.includes(key))acceptDeposit();
 if(!['funding','quote-expired','no-route','low-balance','wrong-network','cancelled-signature','converting','swap-failed','swap-refund','swap-refunded','swap-unknown','converted','awaiting-deposit','deposit-rejected','deposit-unknown','locked','expired'].includes(key))state.match.opponentLocked=true;
 if(key==='ready')state.match.status='ready';if(key==='starting')begin('countdown',3000);
 if(key==='expired'||key==='expired-locked')expire();
 if(['active','disconnected','account-changed','won','lost','draw','payout-sent','payout-error','payout-unknown','payout-confirmed','fee-pending','server-refund'].includes(key)){state.match.status='active';state.match.time=214;state.match.progress=64;state.match.rivalProgress=51;state.page='match';}
 if(key==='disconnected')state.connection='disconnected';if(key==='account-changed')state.wallet='another-player-with-a-very-long-account-name.demo.near';
 if(['won','lost','draw','payout-sent','payout-error','payout-unknown','payout-confirmed','fee-pending','server-refund'].includes(key))finish(key==='lost'?'lost':key==='draw'?'draw':key==='server-refund'?'interrupted':'won');
 if(key==='payout-sent')state.payout='sent';if(key==='payout-error')state.payout='error';if(key==='payout-unknown')state.payout='unknown';if(key==='payout-confirmed'||key==='fee-pending')acceptPayout();if(key==='fee-pending'){state.feePayout='pending';state.match.status='settlement';}
 if(['cancel-refund','refund-error','refund-sent','refund-confirmed'].includes(key)){state.match.status='cancelled';state.refund='pending';if(key==='refund-error')state.refund='error';if(key==='refund-sent')state.refund='sent';if(key==='refund-confirmed')acceptRefund();}
 if(key==='matches'){state.match.status='cancelled';state.refund='pending';state.page='matches';state.history=[{id:'SL-DEMO-08',status:'completed',stake:'5000000',detail:'You won · Payout confirmed',events:[{id:'DEMO-TX-0008',type:'Payout confirmed',detail:'Archived fictional receipt; 9.70 USDC',time:'2026-11-10T09:00:00Z'}]},{id:'SL-DEMO-09',status:'cancelled',stake:'10000000',detail:'Refund confirmed',events:[]}];}
 render(true);
}
function lab(){const pending=!!state.pending;$('#lab').innerHTML=`<div class="dialog-head"><div><div class="lab-label">UI REVIEW TOOLS</div><h2 id="labTitle">Prototype controls</h2></div>${button('×','close-lab','close')}</div><p>Jump to a state or advance the simulated flow. Loading a scenario replaces only this prototype’s demo session.</p><label for="scenarioSelect">Scenario</label><select id="scenarioSelect">${scenarios.map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select>${button('Load scenario','load-scenario','primary full spaced')}<label class="lab-toggle"><input id="holdWaiting" type="checkbox" ${state.hold?'checked':''}><span>Hold waiting states for review<br><small>Uncheck for automatic 2-second demo steps.</small></span></label><div class="lab-actions">${button('Resolve pending step','resolve','',!pending)}${button('Expire lobby','expire','',!state.match||!['open','funding','ready','starting'].includes(state.match.status))}${button('Add opponent','lab-opponent','',!state.match||!!state.match.opponent)}${button('Fund opponent','lab-fund','',!state.match?.opponent||state.match.opponentLocked)}</div><hr class="separator"><p class="small">No SDKs, RPC or payment calls. The CSP blocks network connections. State is saved only under <span class="mono">${KEY}</span>.</p>${button('Reset demo session','reset','ghost danger full')}`;$('#lab').querySelector('.close').setAttribute('aria-label','Close prototype controls');if(!$('#lab').open)$('#lab').showModal();}
document.addEventListener('click',async e=>{const preset=e.target.closest('[data-amount]');if(preset){state.amount=preset.dataset.amount;state.error='';render();$('#stakeAmount').focus();return;}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();return;}const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
 if(['home','online','join','matches'].includes(a)){resumed=false;go(a);return;}
 if(a==='create'){if(activeMatch()||hasObligation()){resume();toast('Finish the current demo match or refund before creating another.');return;}state.error='';go('create');return;}
 if(a==='wallet')return walletModal();if(a==='close-modal')return closeModal();if(a==='close-lab')return $('#lab').close();if(a==='lab')return lab();
 if(a==='connect'){state.wallet='alex.demo.near';closeModal();const next=modalReturn;modalReturn=null;record('Wallet connected','Fictional NEAR account connected; not backend authentication.');if(next==='create')createLobby();else if(next==='join')joinLobby();else render();toast('Demo wallet connected. No real wallet was opened.');return;}
 if(a==='wallet-error'){openModal('Connection failed',notice('Demo wallet unavailable','Try connecting again or continue practicing without a wallet.','error')+button('Try again','wallet','primary full spaced'));return;}
 if(a==='disconnect'){state.wallet=null;closeModal();render();return;}
 if(a==='switch-account'){state.wallet='another-player-with-a-very-long-account-name.demo.near';closeModal();render();toast('Account changed. Existing match ownership is unchanged.');return;}
 if(a==='restore-account'){state.wallet=account();state.error='';render();return;}
 if(a==='tutorial'||a==='bot'){if(window.SupplyLineIntegration)return window.SupplyLineIntegration.launch(a==='tutorial'?'training':'race');openModal(a==='tutorial'?'Play tutorial':'Race the bot',`<p>This entry point is shown for interface review. The existing English ${a==='tutorial'?'tutorial':'bot race'} remains in the separate game file.</p><p class="small">No wallet is required. This prototype does not start or change your game.</p>${button('Back to main menu','close-modal','primary full')}`);return;}
 if(a==='prefund'){if(activeMatch()||hasObligation()){resume();toast('Finish the current demo match before a separate top-up.');return;}archive();state.swap='idle';state.deposit='idle';state.quoteStatus='idle';go('prefund');return;}
 if(a==='accept-invite'){if(state.note==='full'){openModal('Lobby is full',notice('Lobby is full','Another demo player has reserved the second seat. No financial action was requested.','error')+button('Find another match','close-modal','full spaced'));return;}if(state.note==='self-join'){openModal('Already in this lobby',notice('One account, one seat','Your demo account is already the host. You cannot join as your own opponent.','error'));return;}if(!state.wallet)return walletModal('join');return joinLobby();}
 if(a==='add-opponent'||a==='lab-opponent'){if(state.match&&!state.match.opponent){state.match.opponent='riley.demo.near';state.match.status='funding';record('Opponent joined','Demo terms v1 fixed before deposits.');}if($('#lab').open)$('#lab').close();render();return;}
 if(a==='fund-opponent'||a==='lab-fund'){if(state.match?.opponent){state.match.opponentLocked=true;if(state.deposit==='locked')state.match.status='ready';record('Opponent stake locked','Riley demo funding accepted.');}if($('#lab').open)$('#lab').close();render();return;}
 if(a==='copy'){const input=$('#inviteLink');try{await navigator.clipboard.writeText(input.value);toast('Demo invitation copied.');}catch{input.focus();input.select();toast('Invitation selected. Press Ctrl+C or copy from the field.');}return;}
 if(a==='payment-wallet'){openModal('Connect payment wallet',`<p>A separate source wallet is needed for the Ethereum demo route. Your NEAR account remains the stake owner and payout recipient.</p>${button('Connect demo Ethereum wallet','payment-connected','primary full')}`);return;}
 if(a==='payment-connected'){state.paymentConnected=true;closeModal();render();return;}
 if(a==='fix-network'){state.error='';state.paymentConnected=true;render();toast('Demo payment network switched to Ethereum.');return;}
 if(a==='quote'){if(state.pending||state.swap==='unknown')return;if(state.error==='route'||state.error==='network'){render();return;}if(state.source==='eth'&&!state.paymentConnected)return;state.error='';if(BigInt(state.balances[sources[state.source].balanceKey])<sourceAmount().max){state.error='balance';render();return;}state.swap='idle';state.quoteStatus='valid';state.quoteUntil=Date.now()+60000;render();return;}
 if(a==='convert'){if(state.pending||state.swap==='unknown'||state.swap==='completed')return;if(state.quoteUntil<=Date.now()){state.quoteStatus='expired';render();return;}if(state.match&&['expired','cancelled'].includes(state.match.status))return;openModal('Convert demo funds',`<p>Convert funds into your personal NEAR account. This does not lock a stake.</p>${quote()}${financials()}${paymentDetails()}<div class="actions stacked">${button('Approve demo conversion','submit-convert','primary')}${button('Decline signature','decline-convert','ghost')}</div>`);return;}
 if(a==='submit-convert'){if(!$('#modal').open||state.pending||state.swap==='completed')return;if(state.quoteUntil<=Date.now()){closeModal();state.quoteStatus='expired';render();return;}closeModal();state.error='';begin('swap');return;}
 if(a==='decline-convert'||a==='decline-stake'){closeModal();state.error='signature';render();return;}
 if(a==='confirm-stake')return stakeModal();if(a==='submit-stake'){if(!$('#modal').open||state.pending||state.deposit!=='idle')return;closeModal();state.error='';begin('deposit');return;}
 if(a==='check-swap'){if(state.swap==='unknown'||state.swap==='pending'){if(state.pending?.kind==='swap')clearPending();acceptSwap();record('Conversion reconciled','Checked existing demo operation; no second swap.');render();}return;}
 if(a==='check-swap-refund'){state.swap='refunded';record('Swap refund confirmed','Fictional original source asset refund. No escrow deposit.');render();return;}
 if(a==='check-deposit'){if(state.deposit==='unknown'){acceptDeposit();record('Stake reconciled','Checked existing demo deposit; no second debit.');render();}return;}
 if(a==='start'){if(state.deposit==='locked'&&state.match?.opponentLocked&&state.match.status==='ready'&&sameAccount()){begin('countdown',3000);}return;}
 if(a==='cancel-lobby'){if(state.pending?.kind==='deposit'||state.deposit==='unknown'){openModal('Check stake first',notice('Stake confirmation is unresolved','Check final deposit acceptance before cancellation or refund.','error')+button('Close and check status','close-modal','full spaced'));return;}openModal('Cancel this lobby?',`<p>The match will not start. ${state.deposit==='locked'?money(amounts().stake)+' USDC will become refundable to your NEAR account.':'No stake is locked.'}</p><p class="small">No game fee. Prior swap/network costs are separate. A submitted conversion continues independently.</p><div class="actions stacked">${button('Confirm demo cancellation','confirm-cancel','danger')}${button('Keep lobby open','close-modal','primary')}</div>`);return;}
 if(a==='confirm-cancel'){closeModal();if(!sameAccount())return toast('Reconnect the match account first.');state.match.status='cancelled';if(state.deposit==='locked')state.refund='pending';record('Lobby cancelled','No game fee; conversion and stake tracked separately.');render();return;}
 if(a==='new-lobby'){if(hasObligation())return;archive();go('create');return;}
 if(a==='details'){openModal('Match details',`<p class="mono">${esc(state.match?.id||'No match')} · terms v1</p>${financials()}${terms()}${paymentDetails()}<p class="small spaced">Opening this dialog does not pause the demo match clock.</p>`);return;}
 if(a==='receipts')return receipts();if(a==='resume')return resume();
 if(a==='win'||a==='lose'||a==='draw'){finish(a==='win'?'won':a==='lose'?'lost':'draw');return;}
 if(a==='surrender'){openModal('Surrender this match?',`<p>In the proposed rules, surrender means defeat. The opponent would receive the prize after settlement.</p><div class="actions stacked">${button('Confirm demo surrender','confirm-surrender','danger')}${button('Keep racing','close-modal','primary')}</div>`);return;}
 if(a==='confirm-surrender'){closeModal();finish('lost');return;}
 if(a==='reconnect'){state.connection='connected';render();return;}
 if(a==='send-payout'||a==='retry-payout'){if(['pending','error'].includes(state.payout))begin('payout');return;}
 if(a==='check-payout'){if(['sent','unknown'].includes(state.payout)){if(state.pending?.kind==='payout')clearPending();acceptPayout();render();}return;}
 if(a==='check-fee'){if(state.feePayout==='pending'){state.feePayout='confirmed';state.match.status='completed';record('Game fee confirmed','Separate fee transfer; prize not repeated.');render();}return;}
 if(a==='send-refund'||a==='retry-refund'){if(['pending','error'].includes(state.refund)&&sameAccount())begin('refund');else toast('Reconnect the match account to continue.');return;}
 if(a==='check-refund'){if(['sent','unknown'].includes(state.refund)){if(state.pending?.kind==='refund')clearPending();acceptRefund();render();}return;}
 if(a==='load-scenario'){loadScenario($('#scenarioSelect').value);return;}
 if(a==='resolve'){resolvePending();if($('#lab').open)$('#lab').close();return;}
 if(a==='expire'){expire();if($('#lab').open)$('#lab').close();return;}
 if(a==='reset'){clearPending();state=fresh();resumed=false;$('#lab').close();render(true);toast('Demo session reset. Game saves were not accessed.');return;}
 if(a.startsWith('archive-')){const item=state.history.find(x=>x.id===a.slice(8));openModal('Archived demo match',`<h3>${esc(item.id)}</h3><p>${esc(item.detail)} · ${money(item.stake)} USDC stake</p>${(item.events||[]).map(x=>`<div class="receipt-item"><strong>${esc(x.type)}</strong><p class="mono">${esc(x.id)}</p><p>${esc(x.detail)}</p></div>`).join('')||'<p class="small">No additional simulated receipt details.</p>'}`);}
});
function joinLobby(){if(activeMatch()||hasObligation()){resume();toast('You already have a demo match or unfinished refund.');return;}archive();mkMatch(true);state.match.opponent='riley.demo.near';go('lobby');}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='createForm'){state.amount=$('#stakeAmount').value.trim();const n=parseStake(state.amount);if(n===null){state.error='Enter 1–100 USDC with at most 2 decimal places.';render();$('#stakeAmount').focus();return;}state.error='';if(!state.wallet)return walletModal('create');return createLobby();}if(e.target.id==='joinForm'){state.joinCode=$('#joinCode').value.trim();if(!/^(SL-DEMO-42|.*#join=SL-DEMO-42)$/i.test(state.joinCode)){state.error='This demo invite was not found. Use SL-DEMO-42.';render();$('#joinCode').focus();return;}state.note='';state.amount='5.00';go('join-review');}});
document.addEventListener('input',e=>{if(e.target.id==='stakeAmount'){state.amount=e.target.value;const valid=parseStake(state.amount)!==null;state.error=valid?'':'Enter 1–100 USDC with at most 2 decimal places.';$('#stakeError').textContent=state.error;e.target.setAttribute('aria-invalid',String(!valid));$('#createSummary').innerHTML=valid?financials():'<p class="muted">Enter a valid stake to preview the prize.</p>';save();}});
document.addEventListener('change',e=>{if(e.target.id==='sourceAsset'){if(state.pending||state.swap==='unknown'||state.swap==='completed')return;state.source=e.target.value;state.quoteStatus='idle';state.error='';render();}if(e.target.id==='holdWaiting'){state.hold=e.target.checked;if(state.hold)clearTimeout(timer);else if(state.pending)timer=setTimeout(resolvePending,2200);save();}});
setInterval(()=>{let dirty=false;if(state.pending?.kind==='countdown'&&!state.hold){const count=$('[data-countdown]');if(count)count.textContent=Math.max(1,Math.ceil((state.pending.endsAt-Date.now())/1000));}if(state.match&&['open','funding','ready','starting'].includes(state.match.status)&&state.match.deadline<=Date.now()){expire();dirty=true;}if(state.quoteStatus==='valid'&&state.quoteUntil<=Date.now()&&state.swap==='idle'){state.quoteStatus='expired';dirty=true;}if(state.match?.status==='active'){state.match.time++;if(state.match.time%5===0){state.match.progress=Math.min(96,state.match.progress+1);state.match.rivalProgress=Math.min(95,state.match.rivalProgress+1);if(state.page==='match'){const items=document.querySelectorAll('.progress-player');items.forEach((el,i)=>{const p=i?state.match.rivalProgress:state.match.progress;el.querySelector('.row span').textContent=p+'%';el.querySelector('.bar span').style.width=p+'%';el.querySelector('p').textContent='Iron '+Math.floor(12*p/100)+'/12 · Copper '+Math.floor(6*p/100)+'/6 · Asphalt '+Math.floor(8*p/100)+'/8';});}}save();if(state.page==='match'){const c=$('[data-clock]');if(c)c.textContent=clock();}}const t=$('[data-timer="lobby"]');if(t)t.textContent=remaining();if(dirty)render();},1000);
$('#modal').addEventListener('cancel',()=>{modalReturn=null;});
window.addEventListener('hashchange',()=>{if(location.hash==='#join=SL-DEMO-42'){state.amount='5.00';state.note='';state.amount='5.00';go('join-review');}});
if(location.hash==='#join=SL-DEMO-42'){state.amount='5.00';state.note='';state.page='join-review';}
window.SupplyLineUI={home:()=>go('home')};
render();
})();
